Column() {
  List() {
    ForEach(this.shipments, (shipment: Shipment) => {
      ListItem() { Text(shipment.label) }
    })
  }
  .listDirection(Axis.Vertical)
  .height('100%')
}

renderWorkGallery() {
  List() {
    ForEach(this.works, (item: Work) => {
      ListItem() { WorkCard({ item: item }) }
    })
  }
  .listDirection(Axis.Horizontal)
  .height(160)
}

